<?php if(!defined('ABSPATH'))exit;global $wpdb;$t=ICD_Visitas_Database::table('municipios');$rows=$wpdb->get_results("SELECT * FROM $t ORDER BY nome");$edit=isset($_GET['edit'])?$wpdb->get_row($wpdb->prepare("SELECT * FROM $t WHERE id=%d",absint($_GET['edit']))):null;?>
<div class="wrap icd-admin"><h1>Municípios</h1><form class="icd-form-row" method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><?php wp_nonce_field('icd_save_municipio');?><input type="hidden" name="action" value="icd_save_municipio"><input type="hidden" name="id" value="<?php echo (int)($edit->id??0);?>"><label>Município<input required name="nome" value="<?php echo esc_attr($edit->nome??'');?>"></label><label>UF<input required maxlength="2" name="uf" value="<?php echo esc_attr($edit->uf??'PR');?>"></label><?php if($edit):?><label class="icd-check"><input type="checkbox" name="ativo" <?php checked($edit->ativo);?>> Ativo</label><?php endif;?><button class="button button-primary"><?php echo $edit?'Salvar':'Adicionar';?></button></form><table class="widefat striped"><thead><tr><th>Município</th><th>UF</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?php echo esc_html($r->nome);?></td><td><?php echo esc_html($r->uf);?></td><td><a href="<?php echo esc_url(admin_url('admin.php?page=icd-visitas-municipios&edit='.$r->id));?>">Editar</a></td></tr><?php endforeach;?></tbody></table></div>
